import reactor.netty.resources.ConnectionProvider
import java.time.Duration

class NettyConnectionProviderWithoutMaxOrTimeoutKt {
    private val props: OurNettyConnectionProps = OurNettyConnectionProps()

    fun connectionProviderBad1(): ConnectionProvider {
        return ConnectionProvider.builder("gupProvider") // bad
            //.maxConnections(props.getMaxConnections()) // <-- this line was missing
            .pendingAcquireTimeout(Duration.ofMillis(props.pendingAcquireTimeoutMs.toLong()))
            .pendingAcquireMaxCount(props.pendingAcquireMaxCount)
            .maxIdleTime(props.idleTimeSeconds!!)
            .build()
    }

    fun connectionProviderBad2(): ConnectionProvider {
        return ConnectionProvider.builder("gupProvider") // bad
            .maxConnections(props.maxConnections)
            //.pendingAcquireTimeout(Duration.ofMillis(props.getPendingAcquireTimeoutMs()))
            .build()
    }

    fun connectionProviderBad3(): ConnectionProvider {
        return ConnectionProvider.builder("gupProvider") // bad
            //.maxConnections(props.getMaxConnections())
            //.pendingAcquireTimeout(Duration.ofMillis(props.getPendingAcquireTimeoutMs()))
            .build()
    }

    fun connectionProviderGood(): ConnectionProvider {
        return ConnectionProvider.builder("gupProvider")
            .maxConnections(props.maxConnections)
            .pendingAcquireTimeout(Duration.ofMillis(props.pendingAcquireTimeoutMs.toLong()))
            .build()
    }

    internal inner class OurNettyConnectionProps {
        val maxConnections: Int = 0
        val pendingAcquireTimeoutMs: Int = 0
        val pendingAcquireMaxCount: Int = 0
        val idleTimeSeconds: Duration? = null
    }
}
